-- Custom deal funnel, registry part (docs/specs/funnel/01-specification.md §3.7 / §4 / §5,
-- decisions Q4 + Q10 of 02-open-questions.md). Platform reference data:
--   1. 7 new GENERIC signal codes (base pack, block A «Продажи», stage
--      `active` for every org → in the extraction prompt; R22: no vertical or
--      company content): SALES_RFI_REQUESTED, SALES_BRIEF_RECEIVED,
--      SALES_SHORTLISTED, SALES_FINAL_TERMS, SALES_SELECTED, CONTRACT_SIGNED,
--      SALES_LOST;
--   2. their relations to existing codes;
--   3. platform stage-rule TEMPLATES for them (organization_id NULL, target by
--      stage meaning S2 / S3 / S4 / won / lost);
--   4. two funnel templates (`funnel_template`): b2b_standard, tenders_5.
--      Their config JSON = src/lib/funnel/templates-source.ts (the unit test
--      src/lib/funnel/templates.test.ts compares this file with it);
--   5. one registry version (max + 1) with change rows.
-- Fixed keys + ON CONFLICT DO NOTHING: a re-run, or a DB where an admin
-- already changed these rows, keeps the existing rows. The version is written
-- once (guard on change row 'funnel:summary'). Tenant data (an org's funnel and
-- its stage rules) is NOT here — it goes through applyFunnelConfig.

-- 1. Signal codes ────────────────────────────────────────────────────────────
INSERT INTO "signal_category" ("code", "pack_code", "block_code", "family", "label_ru", "definition_ru", "boundary_ru", "cues_prompt_ru", "synonyms_ru", "anti_cues_ru", "example_ru", "counter_example_ru", "card_note_ru", "weight", "score_rule", "class", "class_by_relation", "kind", "effort", "carries_amount", "asks_us", "inbound_only", "emitted_by", "stage", "display_profile", "recipient_role", "closes_codes", "date_gate", "relevance_days", "trigger_rule", "note_ru") VALUES
  ('SALES_RFI_REQUESTED', 'base', 'A', 'offer', 'Запрос RFI, анкеты или кейсов для оценки в рамках отбора', 'В рамках отбора, тендера или конкурса клиент просит материалы для оценки нашей компании: анкету участника, RFI, кейсы по похожим задачам, сведения о команде, опыте и документах. Есть конкретный отбор или задача, под которые нас оценивают.', 'Общая просьба «пришлите кейсы / презентацию» без задачи и без отбора — SALES_CATALOG_REQUESTED или касание без сигнала. Просьба предложить подход, концепцию или решение по задаче — SALES_BRIEF_RECEIVED. Само приглашение к тендеру с документацией — SALES_TENDER_INVITATION. Анкета проверки контрагента (реквизиты, соответствие) без отбора — CONTRACT_COMPLIANCE_DECLARATION.', ARRAY['заполните анкету участника', 'RFI', 'пришлите кейсы по похожим проектам', 'для участия в отборе пришлите', 'квалификационная анкета', 'опыт выполнения аналогичных работ', 'состав команды и резюме', 'предварительный отбор подрядчиков']::text[], '{"business":["просим заполнить анкету для участия в отборе","направьте, пожалуйста, информацию о компании и релевантный опыт","для включения в список участников требуется","просим предоставить кейсы по аналогичным задачам"],"chat":["скиньте кейсы под нашу задачу, мы собираем участников","заполните, пожалуйста, анкету до пятницы"],"terms":["RFI","request for information","анкета участника","квалификационный отбор","предквалификация","портфолио"],"patterns":["«анкета / кейсы / опыт» + «для участия / для отбора / в рамках конкурса»"]}'::jsonb, '[{"text":"«пришлите презентацию компании, познакомимся»","code":"SALES_CATALOG_REQUESTED"},{"text":"«подготовьте концепцию под нашу задачу»","code":"SALES_BRIEF_RECEIVED"},{"text":"«заполните анкету контрагента для договора»","code":"CONTRACT_COMPLIANCE_DECLARATION"}]'::jsonb, '«Мы проводим отбор подрядчиков на проект следующего года. Просим до 20.11 заполнить анкету участника и приложить 3–5 кейсов по похожим задачам.»', '«Пришлите, пожалуйста, ваши кейсы — посмотрим, может, когда-нибудь пригодится» → общая просьба без задачи и отбора, не этот код.', 'Укажи, какой отбор, что именно запросили и к какому сроку; шаги — подобрать подходящие кейсы, заполнить анкету, отправить к сроку.', 6, 'fixed', 'chance', false, 'event', 'medium', false, true, true, 'parser', 'active', NULL, 'opportunity', '{}'::text[], NULL, 45, NULL, 'Added by the custom deal funnel (docs/specs/funnel §5, decision Q4): generic, active for every org; golden-set eval before relying on automatic moves.
Relations: outranks SALES_CATALOG_REQUESTED on the same item.
Deal effect: per org rule. Template: create a deal / move to S2.'),
  ('SALES_BRIEF_RECEIVED', 'base', 'A', 'offer', 'Получен бриф / RFP с просьбой подготовить решение', 'Клиент присылает бриф, техническое задание или RFP и просит подготовить решение по конкретной задаче: подход, концепцию, план, расчёт или тестовое задание. Обычно есть описание задачи и срок ответа.', 'Запрос материалов о нашей компании или кейсов для отбора — SALES_RFI_REQUESTED. Просьба прислать цену или КП на понятный объём без задачи на решение — SALES_OFFER_REQUESTED / SALES_PRICE_REQUEST. Отдельный макет или презентация вне отбора — SALES_MATERIAL_REQUESTED. Приглашение к тендеру без брифа — SALES_TENDER_INVITATION.', ARRAY['направляем бриф', 'во вложении RFP', 'просим предложить решение', 'техническое задание на проект', 'подготовьте подход и оценку', 'тестовое задание', 'ждём ваше предложение по задаче', 'бриф на проект']::text[], '{"business":["направляем бриф и просим подготовить предложение до","во вложении техническое задание, ждём ваше решение","просим представить концепцию и предварительную смету","приглашаем подготовить решение по задаче"],"chat":["скинули бриф, ждём идеи","вот ТЗ, сделаете решение к среде?"],"terms":["бриф","RFP","request for proposal","ТЗ","техническое задание","тестовое задание"],"patterns":["«бриф / ТЗ / RFP» + «подготовить / предложить» + «решение / подход / концепцию»"]}'::jsonb, '[{"text":"«пришлите кейсы и анкету участника»","code":"SALES_RFI_REQUESTED"},{"text":"«пришлите КП на 50 единиц»","code":"SALES_OFFER_REQUESTED"},{"text":"«пришлите прайс»","code":"SALES_PRICE_REQUEST"}]'::jsonb, '«Во вложении бриф по запуску нового направления. Просим до 28.11 предложить подход, план работ и предварительную оценку бюджета.»', '«Пришлите, пожалуйста, ваш прайс на услуги» → цена без задачи на решение, SALES_PRICE_REQUEST.', 'Укажи задачу из брифа, что нужно подготовить и срок; шаги — разобрать бриф, задать уточняющие вопросы, назначить команду, подготовить решение к сроку.', 8, 'fixed', 'chance', false, 'event', 'complex', true, true, true, 'parser', 'active', NULL, 'opportunity', '{}'::text[], NULL, 45, NULL, 'Added by the custom deal funnel (docs/specs/funnel §5, decision Q4): generic, active for every org; golden-set eval before relying on automatic moves.
Relations: outranks SALES_MATERIAL_REQUESTED on the same item (the brief is the more precise code).
Deal effect: per org rule. Template: create a deal / move to S2.'),
  ('SALES_SHORTLISTED', 'base', 'A', 'offer', 'Клиент подтвердил шорт-лист / следующий тур', 'Клиент сообщает, что мы прошли в шорт-лист, финал или следующий тур отбора, или приглашает на следующий этап (защита, финальная презентация).', 'Приглашение на первую встречу или знакомство — не этот код. Сообщение о выборе нас — SALES_SELECTED. Похвала решению без решения о следующем туре — FEEDBACK_QUALITY_PRAISE. Просьба уточнить детали без подтверждения тура — не этот код.', ARRAY['вы прошли в следующий тур', 'вошли в шорт-лист', 'приглашаем на финальную защиту', 'вы в финале', 'отобрали несколько участников, вы среди них', 'второй этап отбора', 'финальная презентация', 'прошли первый этап']::text[], '{"business":["по итогам первого этапа ваша компания прошла в следующий тур","приглашаем на финальную защиту решения","вы включены в короткий список участников"],"chat":["вы в финале!","вас оставили, ждём на защиту"],"terms":["шорт-лист","short list","финал","второй тур","защита"],"patterns":["«прошли / вошли / включены» + «в шорт-лист / в финал / в следующий тур»"]}'::jsonb, '[{"text":"«мы выбрали вас»","code":"SALES_SELECTED"},{"text":"«отличное решение, спасибо»","code":"FEEDBACK_QUALITY_PRAISE"},{"text":"«давайте познакомимся на встрече»","code":null}]'::jsonb, '«По итогам рассмотрения предложений ваша компания вошла в шорт-лист из трёх участников. Приглашаем на финальную защиту 3 декабря.»', '«Спасибо, решение интересное, обсудим внутри» → похвала и пауза, следующий тур не подтверждён.', 'Укажи этап, дату защиты и число участников; шаги — уточнить критерии выбора, подготовить защиту, обновить оценку.', 7, 'fixed', 'chance', false, 'event', 'medium', false, false, true, 'parser', 'active', NULL, 'opportunity', '{}'::text[], NULL, 45, NULL, 'Added by the custom deal funnel (docs/specs/funnel §5, decision Q4): generic, active for every org; golden-set eval before relying on automatic moves.
Relations: outranked by SALES_SELECTED on the same item.
Deal effect: per org rule. Template: move to S3.'),
  ('SALES_FINAL_TERMS', 'base', 'A', 'offer', 'Обсуждение финальных условий после рассмотрения решения', 'После рассмотрения нашего решения или предложения клиент обсуждает финальные условия: обновлённую смету, объём работ, цену, сроки, порядок закупки или договора.', 'Ранний вопрос о бюджете или цене до рассмотрения решения — SALES_BUDGET_MENTIONED / SALES_PRICE_REQUEST, не этот код. Просьба пересмотреть цену действующего договора — SALES_RENEGOTIATION. Сообщение о выборе нас — SALES_SELECTED. Подписание — CONTRACT_SIGNED.', ARRAY['пришлите обновлённую смету', 'давайте финализируем условия', 'по итогам защиты обсудим объём', 'готовы обсудить цену и сроки', 'скорректируйте предложение с учётом', 'согласуем финальную стоимость', 'уточним состав работ перед решением', 'условия закупки и оплаты']::text[], '{"business":["по итогам рассмотрения просим направить скорректированное предложение","просим обновить смету с учётом сокращённого объёма","готовы перейти к обсуждению условий"],"chat":["пересчитайте под новый объём, и решим","давайте добьём условия"],"terms":["обновлённая смета","финальное предложение","best and final offer","BAFO","условия закупки"],"patterns":["«после / по итогам» + «презентации / защиты / рассмотрения» + «смета / цена / объём / условия»"]}'::jsonb, '[{"text":"«какой у вас примерно бюджет на такие проекты?»","code":"SALES_BUDGET_MENTIONED"},{"text":"«прошу снизить цену по действующему договору»","code":"SALES_RENEGOTIATION"},{"text":"«мы выбрали вас»","code":"SALES_SELECTED"}]'::jsonb, '«Решение нам понравилось. Просим до пятницы прислать обновлённую смету на сокращённый объём и предложить условия оплаты — после этого примем решение.»', '«На старте скажите, в какую примерно сумму укладываются такие проекты» → ранний вопрос о бюджете, не финальные условия.', 'Укажи, какие условия обсуждаются (объём, цена, сроки) и срок ответа; шаги — пересчитать смету, согласовать условия внутри, отправить финальное предложение.', 7, 'fixed', 'chance', false, 'event', 'medium', true, true, true, 'parser', 'active', NULL, 'opportunity', '{}'::text[], NULL, 30, NULL, 'Added by the custom deal funnel (docs/specs/funnel §5, decision Q4): generic, active for every org; golden-set eval before relying on automatic moves.
Relations: outranks SALES_BUDGET_MENTIONED on the same item.
Deal effect: per org rule. Template: move to S3.'),
  ('SALES_SELECTED', 'base', 'A', 'offer', 'Клиент сообщил о выборе нас', 'Уполномоченное лицо клиента прямо сообщает, что клиент выбрал нас, или приходит официальное уведомление о победе в отборе или конкурсе. Обязательство заказать ещё не оформлено.', 'Похвала решению («очень понравилось», «вы сильнее всех») — не выбор (FEEDBACK_QUALITY_PRAISE). Догадка или неофициальное мнение сотрудника клиента («думаю, выберут вас») — не выбор. Подписанный договор или оформленный заказ — CONTRACT_SIGNED / SALES_BOOKING_RECEIVED. Прохождение в следующий тур — SALES_SHORTLISTED.', ARRAY['мы выбрали вас', 'приняли решение работать с вами', 'вы победили в конкурсе', 'уведомляем о победе', 'по итогам отбора выбран ваш вариант', 'готовим договор с вами', 'решение в вашу пользу', 'вы стали победителем']::text[], '{"business":["по итогам конкурса победителем признана ваша компания","руководство приняло решение в пользу вашего предложения","уведомляем о выборе вашей компании подрядчиком"],"chat":["вы выиграли!","выбрали вас, готовьте договор"],"terms":["победитель","уведомление о победе","протокол подведения итогов","выбор подрядчика"],"patterns":["«выбрали / приняли решение» + «вас / в вашу пользу»"]}'::jsonb, '[{"text":"«ваше решение лучшее из того, что мы видели»","code":"FEEDBACK_QUALITY_PRAISE"},{"text":"«думаю, руководство выберет вас»","code":null},{"text":"«вы прошли в финал»","code":"SALES_SHORTLISTED"},{"text":"«договор подписан, скан во вложении»","code":"CONTRACT_SIGNED"}]'::jsonb, '«Сообщаем, что по итогам конкурса выбрано ваше предложение. В ближайшие дни направим проект договора.»', '«Презентация была очень сильной, нам всё понравилось» → похвала, решения о выборе нет.', 'Укажи, кто сообщил о выборе и что дальше по оформлению; шаги — поблагодарить, запросить проект договора или заказа, согласовать старт.', 8, 'fixed', 'chance', false, 'event', 'medium', true, false, true, 'parser', 'active', NULL, 'opportunity', '{}'::text[], NULL, 30, NULL, 'Added by the custom deal funnel (docs/specs/funnel §5, decision Q4): generic, active for every org; golden-set eval before relying on automatic moves.
Relations: outranks SALES_SHORTLISTED; outranked by CONTRACT_SIGNED on the same item.
Deal effect: per org rule. Template: move to S4 (a win without a confirmed order stays there).'),
  ('CONTRACT_SIGNED', 'base', 'A', 'contract', 'Подписан договор, оформлен твёрдый заказ или принята оферта', 'Клиент оформил обязательство заказать согласованную работу или товар: подписан договор или дополнительное соглашение, оформлен обязательный заказ, принята оферта. Сделка закрывается как выигранная; оплата — отдельный факт.', 'Победа или устный выбор без оформленного обязательства — SALES_SELECTED. Отправка нами договора на подпись — не этот код (наше действие). Оплата счёта — INVOICE_PAID. Подтверждение заказа без договора (подписанная заявка, гарантийное письмо) — SALES_BOOKING_RECEIVED. Согласование текста договора без подписи — не этот код.', ARRAY['договор подписан', 'подписанный договор во вложении', 'дополнительное соглашение подписано', 'принимаем оферту', 'направляем подписанный заказ', 'акцептуем ваше предложение', 'договор вступил в силу', 'подписали с нашей стороны']::text[], '{"business":["направляем подписанный с нашей стороны договор","дополнительное соглашение подписано, оригиналы направим почтой","настоящим акцептуем оферту"],"chat":["подписали, скан скинула","договор у вас в ЭДО, подписан"],"terms":["договор","дополнительное соглашение","акцепт оферты","ЭДО","подписанный заказ","PO"],"patterns":["«подписан / подписали» + «договор / допсоглашение / заказ»","«акцепт» + «оферты / предложения»"]}'::jsonb, '[{"text":"«мы выбрали вас, договор пришлём позже»","code":"SALES_SELECTED"},{"text":"«оплатили счёт»","code":"INVOICE_PAID"},{"text":"«согласовали текст договора, отправляем на подпись»","code":null}]'::jsonb, '«Договор на выполнение работ подписан с нашей стороны, скан во вложении, оригиналы направим курьером. Можно стартовать по графику.»', '«Поздравляем, вы победили! Договор подготовим в течение месяца» → выбор без оформленного обязательства, SALES_SELECTED.', 'Укажи, какой документ подписан, сумму и дату старта; шаги — проверить документ, передать в исполнение, выставить счёт по условиям.', 8, 'fixed', 'chance', false, 'event', 'medium', true, false, true, 'parser', 'active', NULL, 'opportunity', '{}'::text[], NULL, 14, NULL, 'Added by the custom deal funnel (docs/specs/funnel §5, decision Q4): generic, active for every org; golden-set eval before relying on automatic moves.
Relations: outranks SALES_SELECTED and SALES_BOOKING_RECEIVED on the same item.
Deal effect: per org rule. Template: outcome won.'),
  ('SALES_LOST', 'base', 'A', 'offer', 'Клиент выбрал другого / отменил закупку', 'Клиент прямо сообщает, что выбрал другого участника или поставщика, отменил закупку или конкурс, или что возможность закрыта не в нашу пользу.', 'Молчание клиента — не проигрыш (SALES_OFFER_NO_RESPONSE). Просьба пересчитать предложение — не этот код (COMPLAINT_PRICE / SALES_FINAL_TERMS). Перенос решения — DECISION_POSTPONED. Отказ от одной версии нашего предложения без итога всей возможности — SALES_OFFER_DECLINED. Отмена уже размещённого заказа — SALES_BOOKING_CANCELLED.', ARRAY['выбрали другого подрядчика', 'победителем признан другой участник', 'конкурс отменён', 'закупку решили не проводить', 'проект закрыт', 'вы не прошли в финал', 'приняли решение не в вашу пользу', 'отменяем отбор']::text[], '{"business":["по итогам конкурса победителем признан другой участник","закупка отменена в связи с изменением планов","приняли решение работать с другим подрядчиком"],"chat":["увы, взяли других","проект свернули, конкурса не будет"],"terms":["протокол итогов","отмена закупки","отказ","не прошли"],"patterns":["«выбрали / победил» + «другой / другого»","«отмена / отменён» + «конкурс / закупка / проект»"]}'::jsonb, '[{"text":"тишина после защиты","code":"SALES_OFFER_NO_RESPONSE"},{"text":"«дорого, пересчитайте»","code":"COMPLAINT_PRICE"},{"text":"«решение отложили до весны»","code":"DECISION_POSTPONED"}]'::jsonb, '«Благодарим за участие. По итогам конкурса выбран другой подрядчик; будем рады видеть вас в следующих отборах.»', '«Пока не готовы принять решение, вернёмся после праздников» → перенос, не проигрыш.', 'Укажи, кого выбрали или почему отменили закупку и названную причину; шаги — поблагодарить, запросить обратную связь, записать причину, договориться о следующем контакте.', 7, 'fixed', 'risk', false, 'event', 'medium', false, false, true, 'parser', 'active', NULL, 'opportunity', ARRAY['SALES_OFFER_NO_RESPONSE', 'SALES_MATERIAL_NO_RESPONSE']::text[], NULL, 14, NULL, 'Added by the custom deal funnel (docs/specs/funnel §5, decision Q4): generic, active for every org; golden-set eval before relying on automatic moves.
Closes: SALES_OFFER_NO_RESPONSE, SALES_MATERIAL_NO_RESPONSE (an explicit outcome ends the wait).
Relations: outranks SALES_OFFER_DECLINED; leads over SALES_OFFER_NO_RESPONSE.
Deal effect: per org rule. Template: outcome lost, requires confirmation (silence is never a loss).')
ON CONFLICT ("code") DO NOTHING;
--> statement-breakpoint
