INSERT INTO "funnel_template" ("code", "label_ru", "description", "sort", "config", "is_active") VALUES
  ('b2b_standard', 'Продажи B2B (стандарт)', 'Классическая воронка B2B-продаж: квалификация, выявление потребности, пилот, предложение, переговоры. Сделка создаётся по сигналу клиента; прогноз — по вероятности стадии.', 1, '{"v":1,"stages":[{"code":"area0","name":"Контакт до запроса","role":"area0","description":"Работа с целевой компанией: карта людей, касания до появления конкретной возможности. Зона отношений, а не стадия сделки.","entryCondition":"Известна компания или человек; запроса и решения о продаже может не быть.","signalsHint":"Знакомство, ответ на письмо, встреча на мероприятии, переход знакомого человека в другую компанию; новость или публичное упоминание как повод для контакта. Сохраняем контекст, гипотезу потребности, владельца отношений и следующий шаг. В прогноз не входит.","inForecast":false,"probabilityMode":"stage","probability":0},{"code":"s1","name":"Квалификация","role":"active","description":"Есть потребность или запрос клиента; проверяем, подходит ли возможность нам.","entryCondition":"Клиент обратился с конкретной потребностью, запросом или приглашением к закупке.","signalsHint":"Новая потребность клиента, приглашение к тендеру или закупке.","inForecast":true,"probabilityMode":"stage","probability":0.05},{"code":"s2","name":"Выявление потребности","role":"active","description":"Уточняем задачу, объём, сроки и участников решения у клиента.","entryCondition":"Клиент делится деталями задачи или просит материалы по ней.","signalsHint":"Бриф или RFP, анкета или RFI в рамках отбора, запрос индивидуальных материалов.","inForecast":true,"probabilityMode":"stage","probability":0.2},{"code":"s3","name":"Пилот","role":"active","description":"Клиент проверяет решение на практике: образцы, тест, пилотный проект.","entryCondition":"Клиент запросил образцы, тестовое задание или пилот.","signalsHint":"Запрос образцов, теста или пилотного проекта.","inForecast":true,"probabilityMode":"stage","probability":0.5},{"code":"s4","name":"Предложение","role":"active","description":"Готовим и защищаем коммерческое предложение по задаче клиента.","entryCondition":"Клиент запросил коммерческое предложение по конкретной задаче или включил нас в шорт-лист.","signalsHint":"Запрос КП, подтверждённый шорт-лист или следующий тур.","inForecast":true,"probabilityMode":"stage","probability":0.6},{"code":"s5","name":"Переговоры","role":"active","description":"Согласуем финальные условия: цену, объём, сроки и договор.","entryCondition":"Клиент обсуждает финальные условия после рассмотрения предложения или сообщил, что выбрал нас.","signalsHint":"Обсуждение финальных условий, сообщение клиента о выборе нас.","inForecast":true,"probabilityMode":"stage","probability":0.8},{"code":"won","name":"Выиграна","role":"won","description":"Заказ или договор подтверждён клиентом.","entryCondition":"Клиент подписал договор или дополнение, оформил обязательный заказ или принял оферту.","signalsHint":"Подписанный договор, подтверждённый заказ, принятая оферта. Оплата — отдельный факт.","inForecast":false,"probabilityMode":"stage","probability":1},{"code":"lost","name":"Не состоялась","role":"lost","description":"Клиент выбрал другого или отменил закупку.","entryCondition":"Подтверждённый отказ или отмена; причина указана.","signalsHint":"Явный отказ, выбор другого поставщика, отмена закупки. Молчание клиента — не отказ.","inForecast":false,"probabilityMode":"stage","probability":0}],"dealTypes":[{"code":"new_client","label":"Новый клиент"},{"code":"extra_order","label":"Дополнительный заказ действующего клиента"},{"code":"renewal","label":"Продление договора"}],"reasons":{"lost":[{"code":"competitor","label":"Выбрали другого"},{"code":"cancelled","label":"Клиент отменил закупку"},{"code":"price","label":"Цена"},{"code":"other","label":"Другое"}],"noGo":[{"code":"not_our_profile","label":"Не наш профиль"},{"code":"low_chances","label":"Низкие шансы"},{"code":"no_resources","label":"Нет ресурсов"},{"code":"other","label":"Другое"}],"withdrawn":[{"code":"decided_to_stop","label":"Решили не участвовать дальше"},{"code":"other","label":"Другое"}]},"entryGate":"none","rules":[{"signal":"SALES_TENDER_INVITATION","effect":"create_deal","stage":"s1","dealTypes":[],"requiresConfirmation":false,"minConfidence":"medium","enabled":true},{"signal":"SALES_NEW_DEMAND","effect":"create_deal","stage":"s1","dealTypes":[],"requiresConfirmation":false,"minConfidence":"medium","enabled":true},{"signal":"SALES_RFI_REQUESTED","effect":"create_deal","stage":"s2","dealTypes":[],"requiresConfirmation":false,"minConfidence":"medium","enabled":true},{"signal":"SALES_RFI_REQUESTED","effect":"move_stage","stage":"s2","dealTypes":[],"requiresConfirmation":false,"minConfidence":"high","enabled":true},{"signal":"SALES_BRIEF_RECEIVED","effect":"create_deal","stage":"s2","dealTypes":[],"requiresConfirmation":false,"minConfidence":"medium","enabled":true},{"signal":"SALES_BRIEF_RECEIVED","effect":"move_stage","stage":"s2","dealTypes":[],"requiresConfirmation":false,"minConfidence":"high","enabled":true},{"signal":"SALES_MATERIAL_REQUESTED","effect":"move_stage","stage":"s2","dealTypes":[],"requiresConfirmation":false,"minConfidence":"high","enabled":true},{"signal":"SAMPLES_REQUESTED","effect":"move_stage","stage":"s3","dealTypes":[],"requiresConfirmation":false,"minConfidence":"high","enabled":true},{"signal":"SALES_OFFER_REQUESTED","effect":"move_stage","stage":"s4","dealTypes":[],"requiresConfirmation":false,"minConfidence":"high","enabled":true},{"signal":"SALES_SHORTLISTED","effect":"move_stage","stage":"s4","dealTypes":[],"requiresConfirmation":false,"minConfidence":"high","enabled":true},{"signal":"SALES_FINAL_TERMS","effect":"move_stage","stage":"s5","dealTypes":[],"requiresConfirmation":false,"minConfidence":"high","enabled":true},{"signal":"SALES_SELECTED","effect":"move_stage","stage":"s5","dealTypes":[],"requiresConfirmation":false,"minConfidence":"high","enabled":true},{"signal":"CONTRACT_RENEWAL_INTENT","effect":"create_deal","stage":"s5","dealTypes":["renewal"],"requiresConfirmation":false,"minConfidence":"medium","enabled":true},{"signal":"CONTRACT_SIGNED","effect":"outcome_won","stage":null,"dealTypes":[],"requiresConfirmation":false,"minConfidence":"high","enabled":true},{"signal":"SALES_BOOKING_RECEIVED","effect":"outcome_won","stage":null,"dealTypes":[],"requiresConfirmation":false,"minConfidence":"high","enabled":true},{"signal":"SALES_LOST","effect":"outcome_lost","stage":null,"dealTypes":[],"requiresConfirmation":true,"minConfidence":"high","enabled":true},{"signal":"SALES_OFFER_DECLINED","effect":"outcome_lost","stage":null,"dealTypes":[],"requiresConfirmation":true,"minConfidence":"high","enabled":true},{"signal":"DECISION_POSTPONED","effect":"pause","stage":null,"dealTypes":[],"requiresConfirmation":true,"minConfidence":"medium","enabled":true},{"signal":"SALES_BUDGET_MENTIONED","effect":"in_stage","stage":null,"dealTypes":[],"requiresConfirmation":false,"minConfidence":"medium","enabled":true},{"signal":"SALES_PRICE_REQUEST","effect":"in_stage","stage":null,"dealTypes":[],"requiresConfirmation":false,"minConfidence":"medium","enabled":true},{"signal":"SALES_RENEGOTIATION","effect":"in_stage","stage":null,"dealTypes":[],"requiresConfirmation":false,"minConfidence":"medium","enabled":true},{"signal":"MEETING_NEW_STAKEHOLDER","effect":"in_stage","stage":null,"dealTypes":[],"requiresConfirmation":false,"minConfidence":"medium","enabled":true},{"signal":"CONTACT_NEW_DECISION_MAKER","effect":"in_stage","stage":null,"dealTypes":[],"requiresConfirmation":false,"minConfidence":"medium","enabled":true}]}'::jsonb, true)
ON CONFLICT ("code") DO NOTHING;
