-- 5. Registry version (max + 1) and change log — written once ─────────────────
DO $$
DECLARE v integer;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "signal_registry_change" WHERE "id" = 'funnel:summary') THEN
    SELECT coalesce(max("version"), 0) + 1 INTO v FROM "signal_taxonomy_version";
    INSERT INTO "signal_taxonomy_version" ("version", "summary") VALUES
      (v, 'Воронка сделок: 7 общих кодов продаж (запрос RFI, бриф, шорт-лист, финальные условия, выбор нас, договор подписан, проигрыш), связи и шаблоны правил стадий');
